[{"order":1,"type":"heading","text":"Building Mobile Apps with NativeScript and Angular"},{"order":2,"type":"paragraph","text":"NativeScript allows you to build native mobile applications for iOS and Android using web skills. When combined with Angular, it provides a powerful, enterprise-ready framework featuring dependency injection, two-way data binding, and robust routing."},{"order":3,"type":"subheading","text":"Prerequisites and Installation"},{"order":4,"type":"bullet_point","text":"Node.js (LTS version recommended)"},{"order":5,"type":"bullet_point","text":"NativeScript CLI installed globally via npm"},{"order":6,"type":"bullet_point","text":"Xcode for iOS development (macOS required)"},{"order":7,"type":"bullet_point","text":"Android Studio and Android SDK for Android development"},{"order":8,"type":"paragraph","text":"To install the NativeScript CLI globally, run the following command in your terminal:"},{"order":9,"type":"code","text":"npm install -g nativescript"},{"order":10,"type":"subheading","text":"Creating a New NativeScript Angular Project"},{"order":11,"type":"paragraph","text":"Use the NativeScript CLI to create a new project with the Angular template:"},{"order":12,"type":"code","text":"ns create MyAngularApp --template @nativescript/template-blank-ng"},{"order":13,"type":"paragraph","text":"Navigate into your newly created project directory:"},{"order":14,"type":"code","text":"cd MyAngularApp"},{"order":15,"type":"subheading","text":"Understanding the Component Structure"},{"order":16,"type":"paragraph","text":"NativeScript Angular apps use native UI components instead of HTML elements. For example, instead of a 'div' or 'button', you use 'GridLayout', 'Button', and 'Label'."},{"order":17,"type":"paragraph","text":"Here is an example of a component template (item.component.html) using Angular data binding:"},{"order":18,"type":"code","text":"<GridLayout class="page">
    <StackLayout class="form">
        <Label [text]="message" class="title"></Label>
        <Button text="Tap Me" (tap)="onButtonTap()" class="btn btn-primary"></Button>
    </StackLayout>
</GridLayout>"},{"order":19,"type":"paragraph","text":"And the corresponding component TypeScript file (item.component.ts):"},{"order":20,"type":"code","text":"import { Component, OnInit } from '@angular/core';

@Component({
    selector: 'ns-item',
    templateUrl: './item.component.html'
})
export class ItemComponent implements OnInit {
    message: string = 'Hello NativeScript with Angular!';

    constructor() {}

    ngOnInit(): void {}

    onButtonTap(): void {
        this.message = 'Button was tapped!';
    }
}"},{"order":21,"type":"subheading","text":"Running Your Application"},{"order":22,"type":"paragraph","text":"To run your app on an Android emulator or connected device, execute:"},{"order":23,"type":"code","text":"ns run android"},{"order":24,"type":"paragraph","text":"To run your app on an iOS simulator (macOS only), execute:"},{"order":25,"type":"code","text":"ns run ios"}]
